  ('killington-vermont', '12A', 'Killington', 'United States', 'The Beast of the East', 'live', 'verified', 'northernLights', 'New England', '{"adventure","culinary","entertainment","expedition","family","romance","ski","wellness"}', '{}', '{"essential","comfort","premier","ultra"}', null, 'emerging', '{"key_facts":["Killington = ''The Beast of the East'', the LARGEST ski area in the eastern US; six interconnected peaks (Killington, Snowdon, Skye, Ramshead, Bear, Sunrise); 1,509 acres, 155 trails (212 incl affiliated Pico Mountain, same pass)","New England''s BIGGEST vertical (3,050 ft) off a 4,229-ft summit (Killington Peak; 2nd-highest in the Green Mtns); base 1,165 ft; K-1 Express + Skyeship gondolas among 21 lifts; ~250 in snow + ~71% snowmaking","LONGEST SEASON IN THE EAST: typically late Oct-late May (200+ days), first open (October) + last to close (Superstar into May/June via snowmaking); the ''King of Spring''","OWNERSHIP CORRECTED: no longer Powdr - bought by the local Killington Independence Group on 27 Sep 2024 (Powdr retained a minority stake); on the Ikon Pass (Beast 365 Pass includes Ikon Base; full-Ikon upgrade available)","Stifel Killington Cup = FIS Alpine WORLD CUP (women''s GS + slalom) on Superstar every Thanksgiving weekend since 2016 (one of few US World Cup races; Shiffrin won slalom the first 5 editions); FIS confirms 28-29 Nov 2026","US-TRAFFIC CANDOR: among the most-visited Eastern resorts but no per-resort count published - consensus only","Killington Road (''the Access Road'') = a genuine apres/nightlife strip (The Wobbly Barn); closest commercial airport Rutland (RUT, Cape Air to Boston ~40 min); Boston + NY/NJ drive market; ~15 mi from Rutland","NO on-site cat/heli (fully lift-served); NO natural hot springs (none in region); NO avalanche center (low-avalanche Eastern terrain - ice/cold/driving spine); MID-MARKET (not ultra-luxury); Ikon/lift prices dynamic; summer bike park + golf + Beast Mountain Coaster"],"safety":{"emergency":"911 (police/fire/medical/rescue dispatch); alert ski patrol on-mountain","hospital":"Rutland Regional Medical Center, Rutland (~15 mi) - 144 beds, largest community hospital in Vermont, full 24/7 emergency department","malaria":"none","yellow_fever":"not required","activity_note":"NO AVALANCHE CENTER governs Killington (low-avalanche, patrolled, lift-served Eastern terrain - do NOT cite CAIC/UAC/BTAC/GNFAC); ALTITUDE is LOW (summit 4,229 ft - AMS not a factor); the winter spine is ICE/HARDPACK (''Eastern ice''/boilerplate - sharp edges, ski in control), extreme COLD + WIND CHILL on the exposed summit (frostbite/hypothermia - layer, cover skin, warm-up breaks), and VERMONT WINTER DRIVING (US-4, VT-100, the steep Killington Road/Access Road - winter tires/chains, check VTrans 511vt.com); tree-wells in glades; terrain-park risk at Bear","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Thanksgiving/Killington Cup + early open, Christmas/NY, MLK, Presidents'' Week, mid-winter weekends) - drive-market resort","shoulder":"unusually long: Oct-early Dec early shoulder (first in the East to open) + late shoulder into May/June (Superstar spring skiing)","green":"Jun-Oct second season (bike park, golf, coaster); true lulls at the mud-season edges","booking_lead":"Christmas/NY + Presidents'' + Killington Cup weekend 2-4 mo (holidays/Cup longer); Grand Hotel + Killington Road lodging earliest; Ikon by early fall","off_season_specials":"long early/late shoulders (Oct opening, May/June Superstar); summer bike park + golf + coaster; midweek value","event_peaks":"Stifel Killington Cup (Thanksgiving weekend; FIS confirms 28-29 Nov 2026), Christmas/NY, MLK + Presidents'', spring King-of-Spring/pond-skim (dates verify)","fire_date":"FIRE fall wave (Sep-Nov) Ikon renewals + Killington Cup + early-opening buzz; fire the long tail again Feb-Mar (spring-skiing push)"},"jewels":[{"name":"Ski the Beast - six peaks in a day","status":"live","tier":"comfort","price_band":"window dynamic; package best value","timing":"ski Oct-May","draw_rank":1,"hook":"1,509 acres across six interconnected peaks is the largest ski area in the East — a full day''s exploration without repeating","si":"ski","blurb":"1,509 acres across six interconnected peaks is the largest ski area in the East — a full day''s exploration without repeating","when":"ski Oct-May","commission":"DMC/ski-op 10-15% (embedded-capable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ski"],"shelf_fit":{"adventure":"destination","culinary":"destination","entertainment":"destination","expedition":"destination","family":"destination","romance":"destination","ski":"primary","wellness":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["operator","DMC"],"commission_embedded":true,"commission_basis":"band+lane"},{"name":"Ride the K-1 Gondola to the summit","status":"live","tier":"comfort","price_band":"within package","timing":"High winter","draw_rank":2,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the K-1 Express climbs to Killington Peak for New England''s biggest vertical — the signature descent","si":"ski","blurb":"the K-1 Express climbs to Killington Peak for New England''s biggest vertical — the signature descent","when":"High winter","commission":"within package","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","ski"],"shelf_fit":{"adventure":"evidenced","culinary":"destination","entertainment":"destination","expedition":"destination","family":"destination","romance":"destination","ski":"primary","wellness":"destination"},"commission_lane":["package"],"commission_embe