  ('mt-hood-meadows-oregon', '12A', 'Mt. Hood Meadows (+ Skibowl)', 'United States', 'The biggest terrain on Mt', 'live', 'verified', 'northernLights', 'Pacific Northwest', '{"ski","family","culinary","romance"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Mt. Hood Meadows = largest ski area on Mt. Hood (~2,150 acres, 11 lifts, 85 runs, ~430 in snow; base ~5,300 ft / top ~7,300 ft via Cascade Express); Heather Canyon expert terrain; night skiing (~5-9 p.m., Wed-Sun)","Independent + family-owned (Drake family, founded 1968, CEO Matthew Drake) — one of the largest independently owned resorts in the US; on the Indy Pass","FOLDED IN — Mt. Hood Skibowl: closest ski area to Portland (<1 hr, Government Camp US-26); largest night-skiing terrain in the US (Cosmic Tubing under 600,000+ LEDs); on the Mt. Hood Fusion Pass with Timberline","Skibowl summer Mt. Hood Adventure Park — Alpine Slide (half-mile dual), ziplines, bungee, Skibowl Raceway, 20+ attractions","Meadows on OR-35; Skibowl on US-26 at Government Camp; no on-mountain lodging (Government Camp/corridor/Hood River/Portland beds)","Mt. Hood = active glaciated stratovolcano; NWAC covers the backcountry zone","Providence Hood River Mountain Clinic in the Meadows base area; Legacy Mount Hood Medical Center (Gresham) nearest full hospital"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"Providence Hood River Mountain Clinic in the Meadows base area (ski injuries, in season); nearest hospitals Providence Hood River Memorial + Legacy Mount Hood Medical Center (Gresham, 24/7 ER); serious cases to Portland trauma centers; mountain rescue via county sheriffs + Portland Mountain Rescue / 911","malaria":"none","yellow_fever":"not required","activity_note":"AVALANCHE beyond ropes (heavy maritime snowpack; check NWAC, guide + beacon/probe/shovel; Heather Canyon patrol-controlled); UPPER-MOUNTAIN EXPOSURE + fast whiteout (active glaciated stratovolcano); Cascade winter driving + ODOT chain control (US-26/OR-35 Government Camp corridor; night/weekend Portland drive-home a real hazard/TripCheck); night-ski cold + darkness; tree wells; summer Adventure-Park activity safety (Alpine Slide/ziplines/bungee)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) + strong weekend/Fri-Sat-night peaks (Portland day-and-night market); Skibowl summer Adventure Park Jul-Aug","shoulder":"early season (mid-late Dec), Jan weekdays, late Mar-mid Apr (spring corn), September (warm Adventure-Park shoulder)","green":"mid-Apr-late May + Oct-mid Dec (between-season lulls; some ops reduced — verify)","booking_lead":"Christmas/NY + Government Camp/corridor holiday homes 3-8 mo; Presidents''/Feb 2-5 mo; summer Adventure-Park weekends 1-3 mo; night ski/shoulder/powder days 1-4 wk (day/weekend drive-in Portland market)","off_season_specials":"spring-corn ski deals (late Mar-Apr); summer Skibowl Adventure Park (Jun-Sep) as warm-season engine; night-ski midweek value; Sep Hood/Gorge breaks","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, summer Adventure-Park holidays (Jul 4), night-ski Fri/Sat peaks (verify 2027)","fire_date":"FIRE ski mid-late Mar + late Aug-early Sep; market summer Skibowl Adventure Park by Jan-Feb"},"jewels":[{"name":"Ski the biggest terrain on Mt. Hood","status":"future","tier":"comfort","price_band":"~USD 79-129/day lift","timing":"ski ~mid-Dec-mid Apr, snow-dependent; in-bounds patrolled","draw_rank":1,"hook":"~2,150 acres off eleven lifts — front bowls, long cruisers and the expert plunge of Heather Canyon","si":"ski","blurb":"~2,150 acres off 