-washington","jewels":6,"si":["ski","family","culinary"]},{"id":"timberline-mt-hood-oregon","jewels":8,"si":["ski","ultra","romance","culinary","family","wellness"]}],"orbit_country":["alta-utah","aspen-snowmass-colorado","beaver-creek-colorado","big-sky-montana","breckenridge-colorado","copper-mountain-colorado","crested-butte-colorado","deer-valley-utah","heavenly-california","jackson-hole-wyoming","keystone-colorado","killington-vermont","lake-placid-whiteface-new-york","mammoth-california","northstar-tahoe-california","palisades-tahoe-california","park-city-utah","snowbird-utah","soldier-hollow-utah","steamboat-colorado","stowe-vermont","sugarbush-mad-river-glen-vermont","sunday-river-sugarloaf-maine","telluride-colorado","vail-colorado","white-mountains-new-hampshire","winter-park-colorado"]}'::jsonb, 17),
